head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods15000";

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — kclicUsrTpId, notiResult
// TODO Stage2: 세션 키 실환경 확인(회신 11항) — session.user.kclicUsrTpId

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_spotIsuTrdMktTpCd", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1' || (dma_pageContext.get("kclicUsrTpId") ?? "")==='CHRG_INST_KRX_STK'); } }, { id: "c_when_49", fn: function(){ return (String($c.session.getUserInfo("kclicUsrTpId")).indexOf('CHRG_INST_KRX_') !== -1 ||  $c.session.getUserInfo("kclicUsrTpId") === 'CHRG_INST_ETC'); } }, { id: "c_otherwise_60", fn: function(){ return (!((String($c.session.getUserInfo("kclicUsrTpId")).indexOf('CHRG_INST_KRX_') !== -1 ||  $c.session.getUserInfo("kclicUsrTpId") === 'CHRG_INST_ETC'))); } }, { id: "c_when_75", fn: function(){ return (String($c.session.getUserInfo("kclicUsrTpId")).indexOf('CHRG_INST_KRX_') !== -1 ||  $c.session.getUserInfo("kclicUsrTpId") === 'CHRG_INST_ETC'); } }, { id: "c_otherwise_86", fn: function(){ return (!((String($c.session.getUserInfo("kclicUsrTpId")).indexOf('CHRG_INST_KRX_') !== -1 ||  $c.session.getUserInfo("kclicUsrTpId") === 'CHRG_INST_ETC'))); } }, { id: "if_notiResult", fn: function(){ return (!(String(((dma_pageContext.get("notiResult") ?? "")) === null ? '' : ((dma_pageContext.get("notiResult") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_100", entity: "dlt_notiResult", countIds: [], cells: [{ childId: "btn_goUrl", fn: function (v, i) { return "[가입신청] (" + String(v("etc")) + ") [" + String(v("etc")) + "] " + String(v("title")); } }, { childId: "__rc0", fn: function (v, i) { return " " + String(v("regDate")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.recentKeywrd();
        $("#ipt_formatKeywrd").bind("focus", function() {
                $c.util.getComponent('txt_textSearch').setLabel("");
        });
        $("#ipt_formatKeywrd").bind("focusout", function() {
                if ($(this).val().length === 0) {
                    $c.util.getComponent('txt_textSearch').setLabel("공시 키워드를 입력하십시오.");
                }
        });
        $("#txt_textSearch").bind("click", function() {
                $c.util.getComponent("ipt_formatKeywrd").focus();
        });
        if ($c.util.getComponent('ipt_formatKeywrd').getValue().length === 0) {
            $c.util.getComponent('txt_textSearch').setLabel("공시 키워드를 입력하십시오.");
        }
        for (let i = 0; i < (function(){ throw 'unresolved:list:chgNotiTimer'; })(); i++) {

        }
        confirmF("비밀번호 변경예정일이 ${term}일 남았습니다.\n지금 변경하시겠습니까?", async function() {
                await $c.win.alert('화면 이동 미완 — 목적지 미확인(as-is: /account/mypage.do?method=memberInfoForm). 전환 대상 화면이 확정되면 연결됩니다.');
        });

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods15000.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_conds();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods15000.onpageload' });
    }
};

