/**
 * @method
 * @name goUrl
 * @description go Url 처리
 * @param {*} gb gb
 * @param {*} id id
 * @returns {void}
 * @hidden N
 */
scwin.goUrl = async function (gb, id) {
    if (gb === "NOTI") {
        $c.win.setPageFrameSrc($c.win.getFrame(), '/jldods25000/jldods25000.xml') + id + "&SCREN_ID=ULDODS25010.jsp&SCREN_PROCES_TP_CD=01";
    } else {
        if (gb === "RESO") {
            $c.win.setPageFrameSrc($c.win.getFrame(), '/jldods27000/jldods27000.xml') + id + "&SCREN_ID=ULDODS27010.jsp&SCREN_PROCES_TP_CD=01";
        } else {
            if (gb === "FORM") {
                await scwin.openDocumentPop(id);
            } else {
                $c.win.setPageFrameSrc($c.win.getFrame(), '/jldods16001/jldods16001.xml') + id + "&usrStatId=APPL&SCREN_ID=ULDODS17011.jsp&SCREN_PROCES_TP_CD=01";
            }
        }
    }
};

